INSERT INTO project_authorizations
    (tenant_id, source_project_id, target_project_id, resource_type)
SELECT #{tenantId,jdbcType=VARCHAR}, #{sourceProjectId,jdbcType=VARCHAR},
       #{targetProjectId,jdbcType=VARCHAR}, #{resourceType,jdbcType=VARCHAR}
WHERE NOT EXISTS (
    SELECT 1 FROM project_authorizations
    WHERE tenant_id = #{tenantId,jdbcType=VARCHAR}
      AND source_project_id = #{sourceProjectId,jdbcType=VARCHAR}
      AND target_project_id = #{targetProjectId,jdbcType=VARCHAR}
      AND resource_type = #{resourceType,jdbcType=VARCHAR})

mapper.select:
SELECT DISTINCT target_project_id
FROM project_authorizations
WHERE tenant_id = #{tenantId,jdbcType=VARCHAR}
  AND source_project_id = #{sourceProjectId,jdbcType=VARCHAR}
ORDER BY target_project_id
